{
  "packet_id": "H6-T04-3",
  "claim_id": "C008",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C008.component",
    "value": "Comparisons of account-level event sequences should use accounts of similar age.",
    "scope": "Inspection of invitation, draft-save and publication sequences.",
    "provenance": {
      "refs": [
        {
          "source_id": "P006",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P006 explicitly requires comparing accounts of similar age when inspecting these sequences."
    }
  },
  "signal_basis": {
    "component_id": "C008.signal_basis",
    "value": "Inspect account-level invitation, draft-save and publication sequences, checking event completeness and comparing similarly aged accounts. Individual event patterns can fit several explanations, and recorded events omit offline preparation.",
    "scope": "Descriptive comparisons of recorded onboarding progress, without treating event patterns alone as identifying a mechanism.",
    "provenance": {
      "refs": [
        {
          "source_id": "P006",
          "role": "SUPPORT"
        },
        {
          "source_id": "P021",
          "role": "SUPPORT"
        },
        {
          "source_id": "P004",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans supply the inspection procedure, ambiguity of event patterns and missing offline activity."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C008.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "This supported procedural claim requires no unresolved empirical relation component."
    }
  },
  "rationale": "Account age determines elapsed opportunity to accumulate onboarding events and publish. Comparing accounts of similar age therefore addresses a relevant comparability problem and licenses this limited procedural recommendation. It does not establish that the accounts are otherwise equivalent or that their event sequences identify causes.",
  "uncertainty": "Similar age does not ensure similar roster opportunities or offline preparation, but the claim does not assert that age matching is sufficient.",
  "anomalies": []
}
